<?php
declare(strict_types=1);
require_once __DIR__.'/../../includes/auth.php';
require_once __DIR__.'/../../config/db.php';
requireModuleAccess('customer_orders');
$id=(int)($_GET['id']??0);
$q=$conn->prepare("SELECT o.*,c.customer_name,c.phone,c.address,s.invoice_number,s.sale_date,s.paid_amount,s.balance,s.payment_method FROM customer_sales_orders o JOIN customers c ON c.id=o.customer_id LEFT JOIN sales s ON s.id=o.sale_id WHERE o.id=? AND o.status='Invoiced'");
$q->execute([$id]);$o=$q->fetch();if(!$o){http_response_code(404);exit('Confirmed invoice not found.');}
$q=$conn->prepare("SELECT i.*,p.product_name,p.sku,p.unit FROM customer_sales_order_items i JOIN products p ON p.id=i.product_id WHERE i.order_id=? ORDER BY i.id");$q->execute([$id]);$items=$q->fetchAll();
$company=(string)($conn->query("SELECT setting_value FROM settings WHERE setting_key='company_name' LIMIT 1")->fetchColumn()?:'Dibonke Bookshop');
$currency=(string)($conn->query("SELECT setting_value FROM settings WHERE setting_key='currency' LIMIT 1")->fetchColumn()?:'KES');
$paymentStatus=(float)$o['balance']<=0.001?'PAID':((float)$o['paid_amount']>0?'PARTIALLY PAID':'PAYMENT DUE');
$deliveryQ=$conn->prepare("SELECT id,delivery_number,status FROM deliveries WHERE sale_id=? LIMIT 1");$deliveryQ->execute([(int)$o['sale_id']]);$delivery=$deliveryQ->fetch();
?>
<!doctype html><html><head><meta charset="utf-8"><title>Invoice <?=e($o['invoice_number'])?></title>
<style>
*{box-sizing:border-box}body{margin:0;background:#eef2f7;color:#172b43;font:13px Arial,sans-serif}.actions{display:flex;justify-content:center;gap:10px;padding:16px}.actions button,.actions a{border:0;border-radius:6px;padding:10px 16px;background:#174a7e;color:#fff;text-decoration:none;font-weight:700;cursor:pointer}.actions a.secondary{background:#64748b}.sheet{width:210mm;min-height:297mm;margin:0 auto 24px;padding:17mm 16mm;background:#fff;box-shadow:0 2px 14px #0001}.top{display:flex;justify-content:space-between;gap:24px;border-bottom:3px solid #174a7e;padding-bottom:18px}.brand h1{font-size:25px;margin:0 0 7px;color:#17324d}.brand p,.meta p{margin:4px 0;color:#64748b}.doc-title{text-align:right}.doc-title h2{font-size:26px;letter-spacing:1px;color:#174a7e;margin:0 0 8px}.doc-title strong{font-size:15px}.parties{display:grid;grid-template-columns:1fr 1fr;gap:28px;margin:25px 0}.eyebrow{font-size:10px;color:#64748b;font-weight:800;letter-spacing:1px;text-transform:uppercase;margin-bottom:8px}.party strong{font-size:15px}.party p{margin:5px 0;line-height:1.5}.items{width:100%;border-collapse:collapse;margin-top:18px}.items th{background:#17324d;color:#fff;text-align:left;padding:11px 9px;font-size:11px}.items td{padding:11px 9px;border-bottom:1px solid #e5eaf0;vertical-align:top}.num{text-align:right}.totals{width:310px;margin:20px 0 0 auto}.totals div{display:flex;justify-content:space-between;padding:6px 0}.totals .grand{border-top:2px solid #17324d;margin-top:7px;padding-top:12px;font-size:19px;font-weight:900;color:#17324d}.payment{margin-top:22px;padding:13px 15px;background:#f3f7fb;border-left:4px solid #174a7e;display:flex;justify-content:space-between;gap:12px}.notes{margin-top:25px;color:#475569;line-height:1.5}.foot{margin-top:45px;padding-top:12px;border-top:1px solid #dbe3ec;display:flex;justify-content:space-between;color:#64748b;font-size:10px}.sign{margin-top:60px;display:grid;grid-template-columns:1fr 1fr;gap:45px}.sign div{border-top:1px solid #64748b;padding-top:7px;color:#64748b;font-size:11px}
@page{size:A4;margin:0}@media print{body{background:#fff}.actions{display:none}.sheet{width:210mm;min-height:297mm;margin:0;padding:15mm 15mm;box-shadow:none;page-break-after:avoid}}
</style></head><body>
<div class="actions"><button onclick="window.print()">Print A4 Invoice</button><a href="delivery_note.php?id=<?=$id?>" target="_blank">Print Delivery Note</a><?php if($delivery):?><a class="secondary" href="<?=e('../../deliveries/print.php?id='.(int)$delivery['id'])?>" target="_blank">Delivery Dispatch Copy</a><?php endif;?><a class="secondary" href="index.php">Back to Orders</a></div>
<article class="sheet">
<header class="top"><div class="brand"><h1><?=e($company)?></h1><p>Books · Stationery · General Retail</p><p>Tel: 0706 046963</p></div><div class="doc-title"><h2>INVOICE</h2><strong><?=e($o['invoice_number'])?></strong><p><?=e($o['sale_date'])?></p><p>Order: <?=e($o['order_number'])?></p></div></header>
<section class="parties"><div class="party"><div class="eyebrow">Bill to</div><strong><?=e($o['customer_name'])?></strong><p><?=e($o['phone']??'')?></p><p><?=nl2br(e($o['address']??''))?></p></div><div class="party"><div class="eyebrow">Invoice details</div><p><strong>Invoice date:</strong> <?=e($o['sale_date'])?></p><p><strong>Order reference:</strong> <?=e($o['order_number'])?></p><p><strong>Payment method:</strong> <?=e($o['payment_method']??'Credit')?></p><p><strong>Status:</strong> <?=e($paymentStatus)?></p></div></section>
<table class="items"><thead><tr><th style="width:7%">#</th><th>Item description</th><th style="width:17%">Qty / Unit</th><th class="num" style="width:18%">Unit price</th><th class="num" style="width:20%">Amount</th></tr></thead><tbody><?php foreach($items as $n=>$it):?><tr><td><?=$n+1?></td><td><strong><?=e($it['product_name'])?></strong><?php if(!empty($it['sku'])):?><br><small>SKU: <?=e($it['sku'])?></small><?php endif;?></td><td><?=e($it['entered_quantity'])?> <?=e($it['sale_unit'])?></td><td class="num"><?=e($currency)?> <?=number_format((float)$it['entered_unit_price'],2)?></td><td class="num"><?=e($currency)?> <?=number_format((float)$it['subtotal'],2)?></td></tr><?php endforeach;?></tbody></table>
<div class="totals"><div><span>Subtotal</span><strong><?=e($currency)?> <?=number_format((float)$o['subtotal'],2)?></strong></div><div><span>Discount</span><strong><?=e($currency)?> <?=number_format((float)$o['discount'],2)?></strong></div><div><span>VAT</span><strong><?=e($currency)?> <?=number_format((float)$o['tax'],2)?></strong></div><div class="grand"><span>Total</span><span><?=e($currency)?> <?=number_format((float)$o['total_amount'],2)?></span></div><div><span>Amount paid</span><strong><?=e($currency)?> <?=number_format((float)$o['paid_amount'],2)?></strong></div><div><span>Balance due</span><strong><?=e($currency)?> <?=number_format((float)$o['balance'],2)?></strong></div></div>
<div class="payment"><span><strong>Payment status</strong><br><?=e($paymentStatus)?></span><span><strong>Balance due</strong><br><?=e($currency)?> <?=number_format((float)$o['balance'],2)?></span></div>
<?php if(!empty($o['notes'])):?><div class="notes"><strong>Order notes:</strong> <?=nl2br(e($o['notes']))?></div><?php endif;?>
<div class="sign"><div>Prepared by</div><div>Customer acknowledgement</div></div><footer class="foot"><span>Thank you for your business.</span><span><?=e($o['invoice_number'])?></span></footer>
</article></body></html>